window.TEXTP = window.TEXTP || {};
window.TEXTP["92.1"] = [[["p","33/24 – Первый аят:"],["p","Всевышний Аллах сказал: «И вот (обратившись с мольбой к Аллаху) попросил Муса питья для своего народа», сура «Аль-Бакара»/60 аят."],["sc","img/word-92/image32.webp",295,503,"f"],["c","Книга Погребальной молитвы"],["h2","<b>Книга Погребальной молитвы (1)</b>"],["p","34/1 – Первый аят:"],["p","Всевышний Аллах сказал: «Который создал смерть и жизнь, чтобы испытать вас (о, люди), кто из вас лучше по деяниям [кто более предан и покорен Аллаху]», сура «Аль-Мульк»/2 аят."],["p","35/2 – Второй аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и сторонясь того, что Он запретил) достойным Его остережением и не умирайте (никак) иначе, как будучи только полностью покорными (Ему) [в состоянии Ислама]», сура «Аль Имран»/102 аят."],["h2","<b>Раздел: Совершение молитвы по умершему</b>"],["p","36/3 – Первый аят:"],["p","Всевышний Аллах сказал: «И никогда (о, Посланник) не совершай молитву ни по одному из них, (когда) он умрёт, и не стой над его могилой (чтобы хоронить его и обратиться к Аллаху с мольбой за него). Ведь они стали неверующими в Аллаха и Его посланника и умерли, будучи непокорными [вне Ислама]!», сура «Ат-Тауба»/84 аят."],["h2","<b>Раздел: О погребении умершего</b>"],["p","37/4 – Первый аят:"],["p","Всевышний Аллах сказал: «Разве Мы не сделали Землю (на которой вы живёте) вместилищем (25) для живых (которые на её поверхности) и умерших (которые погребены внутри неё) (26)», сура «Аль-Мурсалят»/25-26 аяты."],["p","(1) Общее число аятов, которые Ибн Касим привел в книге Погребальной молитвы, - 8 аятов."],["sc","img/word-92/image33.webp",294,504,"f"]],[["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","38/5 – Второй аят:"],["p","Всевышний Аллах сказал: «Потом Он [Аллах] умертвил его [человека] и сделал его погребённым (в могилу)», сура «Абаса»/21."],["p","39/6 – Третий аят:"],["p","Всевышний Аллах сказал: «И не стой над его могилой (чтобы хоронить его и обратиться к Аллаху с мольбой за него)», сура «Ат-Тауба»/84 аят."],["h2","<b>Раздел: О посещении могил</b>"],["p","40/7 – Первый аят:"],["p","Всевышний Аллах сказал: «И не стой над его могилой (чтобы хоронить его и обратиться к Аллаху с мольбой за него)», сура «Ат-Тауба»/84 аят."],["h2","<b>Раздел: Соболезнования</b>"],["p","41/8 – Первый аят:"],["p","Всевышний Аллах сказал: «И (Я [Аллах] клянусь, что) Мы (непременно) испытываем вас кое-чем из страха, голода, недостатка в имуществе, (в) душах [смертью] и (в) плодах, – и обрадуй терпеливых (тем, что их в итоге ожидает большое благо в этом мире, и в Вечной жизни), - (155) тех, которые, когда их постигнет (какое-нибудь) бедствие говорят (в душах своих и устами): «Поистине, мы принадлежим Аллаху (и Он поступает с нами, как пожелает), и поистине, мы (только) к Нему возвращаемся (после того, как умрём и мы надеемся получить от Него награду за наше терпение)!»(156) Это – те, над которыми благословения от их Господа [Аллах почтит их тем, что о них будут говорить ангелы небесные] и милость, и они – идущие верным путём (так как правильное проявление терпения является составляющей верного  пути)», сура «Аль-Бакара»/155-157 аяты."],["sep",""],["sc","img/word-92/image34.webp",295,512,"f"],["c","Книга Закята"],["h2","<b>Книга Закята (1)</b>"],["p","42/1 – Первый аят:"],["p","Всевышний Аллах сказал: «И совершайте молитву (должным образом), давайте обязательную милостыню [закят]», сура «Аль-Бакара»/83 аят."],["p","43/2 – Второй аят:"]],[["p","Всевышний Аллах сказал: «Возьми (о, Пророк) с имуществ их [смешавших праведные и плохие деяния и обратившихся с покаянием к Аллаху] милостыню, которой ты очистишь их (от скверны греха) и исправишь их [поднимешь их от положения лицемеров до положения искренних в Вере]. И помолись [обратись с мольбой] за них, ведь твоя молитва [мольба] – успокоение для них, а Аллах – слышащий (каждую мольбу и речь) (и) знающий (положение и намерение Своих рабов)!», сура «Ат-Тауба»/103 аят."],["h2","<b>Глава: Закят, который берется с выращенного на земле</b>"],["p","44/3 – Первый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Расходуйте благое (имущество) из того, что приобрели [дозволенное], и (благое) из того, что извели Мы вам из земли [плоды и полезные ископаемые]. И не намеревайтесь (отдать бедным) плохое из этого, чтобы расходовать, – чего бы вы и сами не взяли (из-за плохого качества), если бы не закрыв на это глаза [очень не хотя]. (И как же вы желаете отдать ради Аллаха то, чего не пожелали себе?) И знайте, что Аллах (Который наделяет вас уделом) богат (и не нуждается в ваших милостынях) и славен!», сура «Аль-Бакара»/267 аят."],["p","(1) Общее число аятов, которые Ибн Касим приводит в книге Закята – (15) аятов."],["sc","img/word-92/image35.webp",294,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Закят с денег (золота и серебра)</b>"],["p","45/4 – Первый аят:"],["p","Всевышний Аллах сказал: «А те, которые накапливают золото и серебро и не расходуют его на пути Аллаха [не выплачивают с него закят], – обрадуй же их мучительным наказанием (34) в тот день [в День Суда], когда в огне Геенны [Ада] будут они [золото и серебро] раскалены и будут клеймиться этим их лбы, и бока, и спины! (И будет им сказано): «Это – то, что вы скопили для самих себя (в земной жизни). Вкушайте же (мучения) (за) то, что вы копили! (35)», сура Ат-Тауба/34-35 аяты."],["h2","<b>Глава: Закят с товара для продажи</b>"]],[["p","46/5 – Первый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Расходуйте благое (имущество) из того, что приобрели [дозволенное]», сура «Аль-Бакара»/267 аят."],["p","47/6 – Второй аят:"],["p","Всевышний Аллах сказал: «И в их имуществах была доля [обязательная и добровольная милостыня]», сура «Аль-Мааридж»/24 аят."],["h2","<b>Глава: Закят аль-фитр</b>"],["p","48/7 – Первый аят:"],["p","Всевышний Аллах сказал: «Уже достиг успеха [спасся от наказания и вошёл в Рай] тот, кто очистился (от неверия и ослушания Аллаха)», сура «Аль-Ааля»/14 аят."],["sc","img/word-92/image36.webp",296,504,"f"],["c","Книга Закята"],["h2","<b>Глава: Выплата закята</b>"],["p","49/8 – Первый аят:"],["p","Всевышний Аллах сказал: «И давайте должное [обязательную милостыню с плодов] во время сбора урожая», сура «Аль-Анам»/141 аят."],["h2","<b>Глава: Кому полагается закят</b>"],["p","50/9 – Первый аят:"],["p","Всевышний Аллах сказал: «(Обязательные) милостыни (предназначены) только для нищих [тех, у которых ничего нет], бедных [тех, которые живут в недостатке], работающих над этим [сборщикам закята], (а также) тем, сердца (которых) привлекаемы (к Исламу) [с надеждой, что они примут Ислам, или принесут пользу верующим или же будет этим отклонено зло от верующих], (а также) для выкупа рабов, (и для) должников (которых обременены долгом), и на пути Аллаха, (и для) путника (который остался без средств продолжать путь), – как обязательное (предписание) от Аллаха. Ведь Аллах – знающий (в чём польза Его рабам) (и) мудрый (в Своих решениях и установлениях)!», сура «Ат-Тауба»/60 аят."],["h2","<b>Глава: Добровольная милостыня</b>"],["p","51/1 – Первый аят:"],["p","Всевышний Аллах сказал: «А дать милостыню [оставить весь долг или часть его должнику] – лучше для вас (и в этом мире и в Вечной жизни)», сура «Аль-Бакара»/280 аят."],["p","52/11 – Второй аят:"]],[["p","Всевышний Аллах сказал: «И давал имущество (как добровольную милостыню), несмотря на любовь (и собственную потребность) к нему, родственникам, и сиротам, и беднякам, и путникам (у которых нет средств продолжать путь), и просящим, и на (освобождение) рабов (и выкуп пленных)», сура «Аль-Бакара»/177 аят."],["sc","img/word-92/image37.webp",293,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","53/12 – Третий аят:"],["p","Всевышний Аллах сказал: «Или накормить в день голода (14)"],["p","сироту из (числа) родственников (15) или бедняка оскудевшего [у которого ничего нет] (16) При этом [при преодолевании препятствия] он был из тех, которые уверовали и заповедовали (между собой) (проявлять) терпение (в делах служения Аллаху и в отстранении от грехов, когда их постигала беда) и заповедовали (между собой) милосердие (по отношению  к рабам Аллаха) (17)», сура «Аль-Баляд»/14-17 аяты."],["p","54/13 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Если вы открыто (даёте) милостыни, то прекрасно это; а если вы скроете их [милостыни], (например, когда) даёте их бедным, то это – лучше для вас (потому что это отдаляет от показухи) и (милостыня, данная исключительно только ради Аллаха) является искуплением для вас за ваши плохие деяния [стирает грехи]: и Аллах сведущ в том, что вы делаете [Он знает ваше положение и воздаст каждому по намерению]!», сура «Аль-Бакара»/271 аят."],["p","55/14 – Пятый аят:"],["p","Всевышний Аллах сказал: «И спрашивают они тебя: что им расходовать (из их имущества в качестве милостыни)? Скажи (им): «Остаток [то, что переходит за ваши потребности]», сура «Аль-Бакара»/219 аят."],["p","56/15 – Шестой аят:"],["p","Всевышний Аллах сказал: «Они отдают предпочтение (мухаджирам) пред собой, хотя бы и было у них стеснение [даже если сами они бедны и нуждаются]. И кого (Аллах) защитил от скупости (и жадности), – то такие (будут) обретшими счастье (в этом мире и в Вечной жизни)!», сура «Аль-Хашр»/9 аят."],["sep",""],["sc","img/word-92/image38.webp",295,502,"f"],["c","Книга Поста"],["h2","<b>Книга Поста (1)</b>"]],[["p","57/1 – Первый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Предписан [сделан обязательным] вам (Аллахом) пост, как он (был) предписан тем (общинам), которые были до вас, чтобы вы этим остереглись (Аллаха) [чтобы вы, будучи покорными Ему и исполняя возложенные Им обязательства, могли отдалиться от совершения грехов] (183)"],["p","на (несколько) отсчитанных дней; а кто из вас болен или в пути [и поэтому не может соблюдать пост], то (на нём обязанность поститься) (определённое) число других дней [по числу пропущенных дней]. А на тех, которые могут это [поститься] (но не постятся, например, из-за старости или смертельной болезни), (то им надлежит отдавать) выкуп (в виде) кормления (одного) бедняка (за каждый пропущенный день). Кто же дополнительно возьмется за благое [будет поститься ещё и кроме обязательных дней или кормить больше чем одного], то это – лучше для него. А соблюдать пост лучше для вас (чем давать выкуп), если бы вы знали (превосходство поста пред Аллахом). (184)"],["p","(Лунный) месяц рамадан, в который ниспослан был Коран (в первый раз) как руководство [источник знаний] для людей и как ясные знамения из (верного) руководства и различения. И кто из вас застает этот месяц [рамадан], пусть соблюдает пост (в дневное время), а кто болен или в пути, то (на нём обязанность поститься) (определённое) число других дней [по числу пропущенных дней]. Аллах хочет для вас облегчения, а не хочет для вас затруднения, и (хочет) чтобы вы довели число (дней поста до месяца) [чтобы постились весь месяц] и (чтобы вы) возвеличивали Аллаха (по завершению поста) за то, что Он вёл вас (даровав необходимые знания и содействуя вам в ваших делах), – и чтобы вы были благодарными (Ему за все дарованные Им блага)!», сура «Аль-Бакара»/183-185 аяты."],["p","(1) Общее число аятов, которые Ибн Касим привел в книге Поста – 8 аятов."],["sc","img/word-92/image39.webp",294,507,"f"]],[["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: О том, что портит пост</b>"],["p","58/2 – Первый аят:"],["p","Всевышний Аллах сказал: «И (также) ешьте и пейте, пока не станет (ясно) различаться перед вами белая нитка [свет дня] от чёрной нитки [темноты ночи] от зари [когда появится заря], потом выполняйте пост до ночи [до захода солнца]», сура «Аль-Бакара»/187 аят."],["h2","<b>Раздел: Об искуплении</b>"],["p","59/3 – Первый аят:"],["p","Всевышний Аллах сказал: «Разрешено вам (Аллахом) в (любую) ночь поста (в рамадан) приближение к вашим женам [иметь близость с ними]: они [жены] – одеяние для вас, а вы (о, мужья) – одеяние для них [для жён] [муж и жена очень нуждаются друг в друге, подобно тому, как человек нуждается в одежде]. Узнал Аллах, что вы обманываете самих себя (совершая недозволенное), и пожалел Он вас (тем, что отменил это трудное положение) и простил вам (то, что вы делали прежде). А теперь (после отмены этого запрета) прикасайтесь к ним [к жёнам] [имейте с ними близость] и ищите того, что предписал Аллах вам [стремитесь получить потомство, которое Аллах вам предопределил], и (также) ешьте и пейте, пока не станет (ясно) различаться перед вами белая нитка [свет дня] от чёрной нитки [темноты ночи] от зари [когда появится заря], потом выполняйте пост до ночи [до захода солнца]», сура «Аль-Бакара»/187 аят."],["h2","<b>Глава: О том, что желательно и не желательно делать во время поста</b>"],["p","Всевышний Аллах сказал: «И отстраняйтесь наилживых речей [измышлений против Аллаха, многобожия и лжесвидетельства]», сура «Аль-Хадж»/30 аят."],["h2","<b>Глава: О восполнении</b>"],["p","61/5 – Первый аят:"],["p","Всевышний Аллах сказал: «А кто болен или в пути, то (на нём обязанность поститься) (определённое) число"],["sc","img/word-92/image40.webp",343,510,"f"],["c","Книга Поста"],["p","других дней [по числу пропущенных дней]. Аллах хочет для вас облегчения, а не хочет для вас затруднения, и (хочет) чтобы вы довели число (дней поста до месяца) [чтобы постились весь месяц] и (чтобы вы) возвеличивали Аллаха (по завершению поста) за то, что Он вёл вас (даровав необходимые знания и содействуя вам в ваших делах), – и чтобы вы были благодарными (Ему за все дарованные Им блага)», сура «Аль-Бакара»/185 аят."],["h2","<b>Глава: Добровольный пост</b>"]],[["p","62/6 – Первый аят:"],["p","Всевышний Аллах сказал: «Кто же дополнительно возьмется за благое [будет поститься ещё и кроме обязательных дней или кормить больше чем одного], то это – лучше для него», сура «Аль-Бакара»/184 аят."],["h2","<b>Раздел: О Ночи Предопределения</b>"],["p","63/7 – Первый аят:"],["p","Всевышний Аллах сказал: «Ночь предопределения лучше тысячи месяцев», сура «Аль-Кадр», 3 аят."],["h2","<b>Глава: О пребывании в мечети с целью поклонения</b>"],["p","64/8 – Первый аят:"],["p","Всевышний Аллах сказал: «И не прикасайтесь к ним [не имейте близость с женами], в то время когда вы находитесь (с усердным поклонением Аллаху) в мечетях [намеренно остаётесь в мечетях на несколько дней]», сура «Аль-Бакара»/187 аят."],["sep",""],["sc","img/word-92/image41.webp",295,504,"f"],["c","Книга Обрядов хаджа"],["h2","<b>Книга Обрядов хаджа (1)</b>"],["p","65/1 – Первый аят:"],["p","Всевышний Аллах сказал: «И перед Аллахом (лежит обязанность) на (всех) людях (совершить) паломничество [хадж] к Дому, – для тех, кто в состоянии [может] (совершить) к нему путь. А кто не верует [не признаёт обязательность совершения паломничества в Запретную Мечеть]... то ведь поистине Аллах – не нуждается в мирах [не нуждается ни в нём, ни в его паломничестве, ни в его деяниях и вообще ни в чём]», сура «Аль-Бакара»/97 аят."],["h2","<b>Глава: О времени хаджа</b>"],["p","66/2 – Первый аят:"],["p","Всевышний Аллах сказал: «Хадж – известные месяцы [шавваль, зуль-ка’да и первые десять дней месяца зуль-хиджжа]», сура «Аль-Бакара»/197 аят."],["h2","<b>Глава: Состояние запретности (ихрам)</b>"],["p","67/3 – Первый аят:"],["p","Всевышний Аллах сказал: «И кто обязался в них [в эти месяцы] (совершить) хадж (войдя в состояние ихрама)», сура «Аль-Бакара»/197 аят."],["p","68/4 – Второй аят:"],["p","Всевышний Аллах сказал: «Тому, кто совершает (отдельную) ‘умру перед хаджем [хадж ат-таматту’]», сура «Аль-Бакара»/196 аят."]],[["p","(1) Общее число аятов, которые Ибн Касим приводит в книге Обрядов хаджа – 18 аятов."],["sc","img/word-92/image42.webp",294,512,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Запрещенные действия во время ихрама</b>"],["p","69/5 – Первый аят:"],["p","Всевышний Аллах сказал: «И не брейте своих голов, пока не дойдет жертва до своего места (на территории аль-Харама) [в день праздника жертвоприношения, то есть десятого зуль-хиджжы, и в дни ат-ташрик, которые следуют после праздника]. А если кто из вас болен или у него страдание в голове (и он вынужденно побреет голову), то (за это на нём будет обязанность совершить) искупление (трёхдневным) постом, или милостынею [накормить шесть бедняков], или жертвой (овцы, мясо которого раздаётся бедным, которые находятся в аль-Хараме). А если вы (находитесь) в безопасности (и здоровы), то тому, кто совершает (отдельную) ‘умру перед хаджем [хадж ат-таматту’], (то) тому (нужно зарезать) то из жертвенных животных, что легко; а кто не найдет (что принести в жертву), то (ему нужно соблюдать) пост три дня во время хаджа и семь, когда вернётесь (к своим семьям); вот – десять полных. Это [жертвоприношение и пост] (назначен) для тех, у кого семья не находится при Запретной (для греха) Мечети», сура «Аль-Бакара»/196 аят."],["p","70/6 – Второй аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Не убивайте добычи (на суше), когда вы (находитесь) в (состоянии) запрета [в ихраме] (во время совершения большого или малого паломничества). А кто убьёт (какое-либо животное или птицу) из вас умышленно, то воздаяние  (ему за этот грех) — (зарезать) (домашнюю) скотину [верблюда, корову, овцу или козу] подобную (по величине тому), что он убил (если есть подобие такого животного из домашнего скота). Устанавливают [определяют] это [что должно быть зарезано] двое справедливых из вас [верующих] как жертву, направляющуюся к Каабе (для неимущих, которые  находятся на Запретной территории), или искупление (этого греха, в случае если нет подобного домашнего животного) — (купить на эту стоимость) еду для бедных (по половине са’а на каждого бедняка) (и накормить их), или взамен этому — (он должен соблюдать) пост (по дню за каждый са’ той еды). Это [Аллах предписал такое воздаяние] — чтобы он вкусил пагубность своего дела [за охоту в состоянии ихрама]. Простил Аллах то, что было уже прежде (этого запрета) [не нужно искупление за прежнее после того, как было установлено такое положение]; а кто вернётся (к ослушанию), тому отмстит Аллах: поистине, Аллах величественен [всемогущ], (и) обладатель мщения (по отношению к тем, которые ослушаются Его)! (95) Дозволена вам (о, верующие) охота в море (на живые морские животные) и еда из него [то, что добыто уже умершим] в пользование вам и путникам. Но запрещена вам охота на суше, пока вы (находитесь) в ихраме. И остерегайтесь (наказания) Аллаха, к Которому вы будете собраны! (96)», сура «Аль-Маида»/95-96 аяты."]],[["p","71/7 – Третий аят:"],["p","Всевышний Аллах сказал: «И кто обязался в них [в эти месяцы] (совершить) хадж (войдя в состояние ихрама), то нет [не позволяется] приближения (к совершению близости ни словами и ни поступками), и ослушания (повелений Аллаха), и препирательства [споров, которые возбуждают гнев и ненависть] во время хаджа», сура «Аль-Бакара»/197 аят."],["sc","img/word-92/image43.webp",340,505,"f"],["c","Книга Обрядов хаджа"],["h2","<b>Глава: Воздаяние за охоту</b>"],["p","72/8 – Первый аят:"],["p","Всевышний Аллах сказал: «А кто убьёт (какое-либо животное или птицу) из вас умышленно, то воздаяние (ему за этот грех) — (зарезать) (домашнюю) скотину [верблюда, корову, овцу или козу] подобную (по величине тому), что он убил (если есть подобие такого животного из домашнего скота). Устанавливают [определяют] это [что должно быть зарезано] двое справедливых из вас [верующих] как жертву, направляющуюся к Каабе (для неимущих, которые находятся на Запретной территории), или искупление (этого греха, в случае если нет подобного домашнего животного) — (купить на эту стоимость) еду для бедных (по половине са’а на каждого бедняка) (и накормить их), или взамен этому — (он должен соблюдать) пост (по дню за каждый са’ той еды). Это [Аллах предписал такое воздаяние] — чтобы он вкусил пагубность своего дела [за охоту в состоянии ихрама]. Простил Аллах то, что было уже прежде (этого запрета) [не нужно искупление за прежнее после того, как было установлено такое положение]; а кто вернётся (к ослушанию), тому отмстит Аллах: поистине, Аллах величественен [всемогущ], (и) обладатель мщения (по отношению к тем, которые ослушаются Его)!», сура «Аль-Маида»/95 аят."],["h2","<b>Глава: Об охоте на территории Аль-Харама</b>"],["p","73/9 – Первый аят:"],["p","Всевышний Аллах сказал: «Неужели они [мекканские многобожники] не видели, что Мы сделали (Мекку, в которой они живут) запретным (для совершения греха) (и) безопасным (местом) а (в то же время) люди [другие арабы], (которые живут) вокруг их, выхватываются [убиваются и берутся в плен]? Неужели в ложь [в многобожие] они веруют, а благодать Аллаха [Истинную Веру] отвергают?», сура «Аль-Анкабут»/67 аят."],["h2","<b>Глава: Вход в Мекку</b>"]],[["p","74/10 – Первый аят:"],["p","Всевышний Аллах сказал: «Пусть они присутствуют при том, что полезно для них [чтобы этим обрести прощение грехам, награду за исполнение обрядов и за повиновение, и получить прибыль от торговли, и другое]», сура «Аль-Хадж»/28 аят."],["p","75/11 – Второй аят:"],["p","Всевышний Аллах сказал: «И (напомни людям, о, Пророк) как, Мы сделали [превратили] этот дом [Каабу] местом возвращения для людей (куда они возвращаются для совершения паломничества и которое они вспоминают перед каждой молитвой, когда берут молитвенное направление) и безопасным местом (где люди в безопасности за себя и за своё имущество, и даже деревья и травы в безопасности от срывания): «И возьмите себе [сделайте] из места стояния Ибрахима место для совершения молитвы», сура «Аль-Бакара»/125 аят."],["sc","img/word-92/image44.webp",294,510,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Описание хаджа</b>"],["h2","<b>Раздел: Об отправлении в долину Аль-Муздалифа</b>"],["p","76/12 – Первый аят:"],["p","Всевышний Аллах сказал: «А когда вы двинетесь с Арафата (после захода солнца, когда закончится стояние там), то поминайте Аллаха (восславляя Его, произнося тальбийю и обращаясь к Нему с мольбами) при заповедном памятнике [в долине Муздалифа]. И поминайте Его (правильным образом), как Он указал вам (на это), хотя до этого [до того, как Он дал истинный путь] вы были из (числа) заблуждающихся», сура «Аль-Бакара»/198 аят."],["h2","<b>Раздел: Об отправлении в Мекку</b>"],["p","77/13 – Первый аят:"],["p","Всевышний Аллах сказал: «Потом пусть они [паломники] покончат со своею неопрятностью [постригут волосы и отстригут ногти] (выходя из состояния ихрама) и полностью выполнят свои обеты (которые они давали относительно жертвоприношений) и пусть обойдут вокруг [совершат обряд таваф] Древнего Дома [Каабы]», сура «Аль-Хадж»/29 аят."],["h2","<b>Раздел: Об отправлении (из Мины в Мекку)</b>"]],[["p","78/14 – Первый аят:"],["p","Всевышний Аллах сказал: «Кто поторопится в два дня [кто захочет выйти из долины Мина до захода солнца двенадцатого числа, после бросания камешек], то не (будет) греха на нём, а кто задержится (и останется ночевать в Мине, чтобы бросать камушки тринадцатого числа), то не (будет) греха на нём; (это) — для того, кто будет остерегаться (наказания) Аллаха (завершая быстрее и задерживаясь. И остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и, сторонясь того, что Он запретил) и знайте, что вы к Нему будете собраны (в День Суда)», сура «Аль-Бакара»/203 аят."],["sc","img/word-92/image45.webp",296,504,"f"],["c","Книга Обрядов"],["h2","<b>Глава: Невозможность совершить хадж и затруднения</b>"],["p","79/15 – Первый аят:"],["p","Всевышний Аллах сказал: «Если же вы затруднены [не можете совершить хадж или ‘умру по каким-либо обстоятельствам уже после того как вошли в состояние ихрама], (то принесите в жертву ради Аллаха) то, что легко из жертвенных животных (в том месте, где вы задержались)», сура «Аль-Бакара»/196 аят."],["h2","<b>Глава: Жертвенное животное и жертвоприношение</b>"],["p","80/16 – Первый аят:"],["p","Всевышний Аллах сказал: «Это — (то, что повелел Аллах)! А кто почитает знаки, (которые установил) Аллах (а это обряды хаджа, его места и принесение в жертву хороших животных), то ведь это (исходит) от остережения  сердец [из признаков людей, которые остерегаются наказания Аллаха и боятся Его наказания]. (32) Для вас в них [в предназначенных для жертвоприношения животных] (есть) польза [пользование шерстью, молоком, использование для передвижения] до определённого срока [до времени жертвоприношения в дни ат-ташрик], а потом место их (где они будут зарезаны) у Древнего Дома [вся Священная территория]. (33) И для каждой (предыдущей) общины установили Мы место (и обряд) жертвоприношения, чтобы они поминали [произносили] имя Аллаха над тем, чем Он наделил их из животных из скота [чтобы возблагодарить Его за это]. Ибо бог ваш (о, люди) — Бог единый. Ему предайтесь [будьте полностью покорными Ему и душой и телом]. А ты (о, Пророк) обрадуй смиренных (что их ожидает благо в этом мире и в Вечной жизни). (34) (И такими смиренными являются только) те, которые когда им напоминают об Аллахе их сердца страшатся [они выполняют то, что повелел Аллах и прекращают совершать то, что Он запретил], и проявляющие терпение (в надежде на награду от Аллаха) в том, что их постигает [во время трудностей и несчастья], и совершающие (обязательную) молитву (надлежащим образом) [своевременно, смиренно перед Господом и предаваясь молитве душой] и (которые) из того, чем Мы наделили их [из своего дозволенного имущества], расходуют (на пути Аллаха, как обязательную и добровольную милостыню). (35)», сура «Аль-Хадж»/32-35 аяты."]],[["p","81/17 - Второй аят (1):"],["p","Всевышний Аллах сказал: «И жертвенных животных (которых гонят в Священную территорию) Мы сделали для вас из (числа) знаков [обрядов], (которые установил) Аллах. Для вас (о, те, которые стремятся к довольству Аллаха) в них [в этих жертвенных животных] благо [вы едите их сами, раздаёте как милостыню, и получаете за это награду в Вечной жизни]. Поминайте же [произносите] имя Аллаха над ними (когда режете их), (а верблюды режутся) стоящими. А когда их бока повергнутся [когда они упадут], то ешьте их [их мясо] (вы сами, кто зарезал их) и кормите (этим мясом)"],["p","(1) Этот аят следует вслед за предыдущими, но он был расположен отдельно в книге «Основы вынесения шариатских постановлений» стр.125, и он сравнил его в своем разъяснении 2/520-523."],["sc","img/word-92/image46.webp",294,505,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","сдержанного [не просящего] и просящего стыдливо. Так Мы подчинили их [жертвенных животных] вам, чтобы вы были благодарны (Аллаху)! (36) Не достигает Аллаха [не поднимается к Нему] ни мясо их [этих жертвенных животных], ни их кровь. Но доходит до Него остережение от вас [ваше намерение этим жертвоприношением только довольства Аллаха, исполняя то, что Он повелел и отстранение от того, что Он запретил]. (37)», сура «Аль-Хадж»/36-37 аяты."],["h2","<b>Раздел: Об акыке (1)</b>"],["p","82/18 – Первый аят:"],["p","Всевышний Аллах сказал: «И освободили Мы (от принесения в жертву) его [Исмаила] (заменив) на великую жертву [барана]», сура «Ас-Саффат»/107 аят."],["sep",""],["p","(1) Жертвоприношение по причине рождения ребенка. (прим. пер.)"],["sc","img/word-92/image47.webp",303,503,"f"],["c","Книга Джихада"],["h2","<b>Книга Джихада (1)</b>"]],[["p","83/1 – Первый аят:"],["p","Всевышний Аллах сказал: «Поистине, Аллах купил у верующих их души [жизни] и их имущества (в обмен) на то, что им (будет дарован) Рай! Они сражаются на пути Аллаха, убивая и погибая. Согласно обещанию от Него истинному (данному) в Торе, Евангелии и Коране. И кто же более верен в (исполнении) своего договора, нежели Аллах? Радуйтесь же (о, верующие) своей сделке, которую вы заключили с Ним! И это [такая сделка] ведь – великий успех!», сура «Ат-Тауба»/111 аят."],["p","84/2 – Второй аят:"],["p","Всевышний Аллах сказал: «Выступайте (о, верующие) (будучи) легкими [молодыми, бедными,…] и (будучи) тяжелыми [пожилыми, богатыми,…] и усердствуйте своими имуществами и душами на пути Аллаха! Это [такой выход и расходование] – лучшее для вас, если бы вы только знали!», сура «Ат-Тауба»/41 аят."],["p","85/3 - Третий аят:"],["p","Всевышний Аллах сказал: «И приготовьте (о, верующие) для них [для встречи с вашими врагами], насколько можете, силы [оружия] и отрядов конницы; вы устрашите этим врага Аллаха, и вашего врага (которые ждут как напасть на вас)», сура «Аль-Анфаль»/60 аят."],["p","(1) Общее чилсо аятов, которые привел Ибн Касим в книге Джихада – 16 аятов."],["sc","img/word-92/image48.webp",294,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","86/4 – Четвертый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Почему, когда говорится вам: «Выступайте [выходите] на пути Аллаха (чтобы сражаться с вашими врагами)», вы припадаете к земле [ленитесь и привязываетесь к своим жилищам]? Неужели вы стали довольными земной жизнью больше чем Вечной? Ведь удел жизни ближней [преходящие блага этого мира] в (сравнении) с Вечной жизнью [с благами Рая] ничтожен», сура «Ат-Тауба»/38 аят."],["h2","<b>Раздел: Об обязательности подчинения</b>"]],[["p","87/5 – Первый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Повинуйтесь Аллаху и повинуйтесь посланнику и обладателям власти среди вас (в том, что не является ослушанием Аллаха). Если же вы препираетесь о чем-нибудь, то верните это Аллаху [рассмотрите в Коране] и Посланнику [смотрите решение в Сунне], если вы (на самом деле) веруете в Аллаха и в Последний День [День Суда]. Это [возвращение к Корану и Сунне] – лучше (чем спор и предположение) и прекраснее по исходу [по итогу]», сура «Ан-Ниса»/59 аят."],["p","88/6 – Второй аят:"],["p","Всевышний Аллах сказал: «И советуйся с ними о деле (которое требует совета). А когда ты (о, Пророк) решился [принял какое-то решение], то уповай (только) на Аллаха, – поистине, Аллах любит уповающих [тех, которые полагаются на Него]!», сура «Аль-Имран»/159 аят."],["p","89/7 – Третий аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Когда встречаете (военный) отряд (неверующих) (приготовившихся к сражению с вами), то будьте стойкими [не проявляйте слабость и малодушие] и поминайте Аллаха много (обращаясь к Нему с мольбами о ниспослании Им помощи вам и победы над врагами), чтобы вы обрели успех (победу в этом мире, и Рай в Вечной жизни) (45) И (всегда) повинуйтесь Аллаху и Его посланнику и не препирайтесь [не спорьте], а не то падёте духом (так как между вами не будет единства), и уйдёт ваша мощь [ослабеете] (из-за разногласий). И терпите (ради Аллаха): поистине Аллах вместе с терпеливыми [помогает им и оказывает Свою поддержку]! (46)», сура «Аль-Анфаль»/45-46 аят."],["sc","img/word-92/image49.webp",338,511,"f"],["c","Книга Джихада"],["p","90/8 – Четвертый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Когда вы встретите тех, которые стали неверующими, наступающими (в битве), то не обращайте к ним тыл [не бегите с поля боя], (а наоборот, будьте стойкими против них, так как Аллах – с вами и Он поможет вам одолеть их). (15) А кто повернётся к ним [к неверующим] в тот день (во время наступления) своим тылом [убегая], кроме как только (если не для показа ложного отступления,) чтобы (затем снова) повернуться к сражению или (кроме как только) для присоединения к отряду (сражающихся верующих, где бы они ни находились), тот [бегущий с поля сражения] навлечёт на себя гнев Аллаха и его прибежищем (будет) Геенна [Ад], и (как) ужасно это возвращение! (16)», сура «Аль-Анфаль»/15-16 аяты."],["h2","<b>Раздел: О трофеях</b>"]],[["p","91/9 – Первый аят:"],["p","Всевышний Аллах сказал: «Ешьте же то, что вы захватили (у неверующих) как трофеи (в борьбе на пути Аллаха) [трофеи и выкуп за пленных] как дозволенное, благое [оно дозволено вам], и остерегайтесь (наказания) Аллаха [соблюдайте положения и решения, которые Он предписал]: поистине, Аллах прощающий (тех Своих рабов, которые каются), (и) милосердный (к верующим)!», сура «Аль-Анфаль»/69 аят."],["p","92/10 – Второй аят:"],["p","Всевышний Аллах сказал: «И знайте (о, верующие), что если вы (в борьбе на пути Аллаха) захватили (у неверующих) трофеями что-либо, то Аллаху принадлежит одна пятая часть [то, что используется на благо всего Ислама], и (эта же самая часть принадлежит) Посланнику [даётся пророку Мухаммаду на личные расходы и содержание его жён на протяжении года], и родственникам (Посланника) [родам бану Хашим и бану Мутталиб, и даётся часть военных трофеев им вместо милостыни, которую Аллах запретил им брать], и сиротам, и бедным (и нищим) (из мусульман), и путнику (у которого закончились средства продолжать путь)», сура «Аль-Анфаль»/41 аят."],["p","93/11 – Третий аят:"],["p","Всевышний Аллах сказал: «А кто (из вас), обманывая, присвоит (себе что-либо) – придёт с тем, что присвоил, в День Воскресения (и будет представлен с позором). Затем всякой душе будет уплачено сполна [будет полностью воздано] за то, что она приобрела [за все благие и плохие деяния], и они не будут обижены [ни насколько не будут убавлены благодеяния, и не будет дано наказание за то плохое, что человек не совершал]», сура «Аль Имран»/161 аят."],["sc","img/word-92/image50.webp",328,503,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Раздел: О трофеях, которые были получены без сражения</b>"],["p","94/12 – Первый аят:"],["p","Всевышний Аллах сказал: «И то, что даровал Аллах как (военную) добычу Своему посланнику от них [из их имущества], то вам для этого не пришлось гнать ни коней, ни (ездовых) верблюдов, но однако Аллах даёт власть Своим посланникам, над кем пожелает [над любыми врагами] (и даже без сражения). И (ведь) Аллах над каждой вещью мощен! (6) И то, что даровал Аллах как (военную) добычу Своему посланнику от обитателей селений [из имущества многобожников] (и при этом не пришлось гнать верховых животных), – то (такая добыча) (не распределяется среди воинов, а) принадлежит Аллаху [расходуется на общее благо всех верующих], Посланнику, родственникам (Пророка), сиротам, бедным, и путнику (у которого закончились средства в пути и он не может продолжать свой путь), чтобы не оказалось это распределением (только) между богатыми из вас. И что дал вам Посланник (будь то имущество или его повеление), то берите это [примите, если имущество, и повинуйтесь, если это его повеление], а что он вам запретил, то от того удержитесь. И остерегайтесь (наказания) Аллаха [выполняйте то, что Он повелел и прекратите совершать то, что Он запретил], ведь поистине Аллах суров в наказании (тех, которые ослушаются Его)! (7) (а также из такой добычи даётся) неимущим переселившимся (в Медину), которые были изгнаны (неверующими) из своих земель [из Мекки] и (лишены) своего имущества, желая щедрости от Аллаха (в этом мире) и (Его) довольства (в Вечной жизни), и (которые) помогают Аллаху и Его посланнику (усердствуя на Его пути). Такие – они являются правдивыми [такими, у которых слова совпадают с делами]! (8) А те [ансары], которые обосновались в обители [в Медине] и Вере [уверовали] до них [прежде чем прибыли к ним мухаджиры], любят переселившихся к ним [мухаджиров] (и помогают им) и не находят в своих грудях [душах]  никакой нужды [зависти] к тому, что даровано им [мухаджирам] (из добычи). Они отдают предпочтение (мухаджирам) пред собой, хотя бы и было у них стеснение [даже если сами они бедны и нуждаются]. И кого (Аллах) защитил от скупости (и жадности), – то такие (будут) обретшими счастье (в этом мире и в Вечной жизни) (9) А те, которые пришли после них [после ансаров и первых мухаджиров], говорят: «Господь наш! Прости нам и нашим братьям (по вере), которые опередили нас в Вере [которые уверовали раньше нас]! И не утверждай в сердцах наших злобы [зависти и ненависти] (по отношению) к тем, которые уверовали. Господь наш! Поистине, Ты – сострадательный, милосердный!», сура «Аль-Хашр»/6-10 аяты."],["h2","<b>Глава: О предоставлении безопасности</b>"]],[["p","95/13 – Первый аят:"],["p","Всевышний Аллах сказал: «А если кто-нибудь из многобожников (с которыми Аллах повелел сражаться) (после завершения запретных месяцев) попросит у тебя (о, Пророк) безопасности (чтобы услышать то, к чему ты призываешь), то предоставь ему безопасность, чтобы он мог услышать"],["sc","img/word-92/image51.webp",295,502,"f"],["c","Книга Джихада"],["p","Слово Аллаха (и узнал об Истинном Пути). Потом (если он не уверует) доставь [сопроводи] его в безопасное для него место [откуда он пришёл] (не совершая по отношению к нему предательства). Это – потому, что они [многобожники] – люди, которые не знают (истинной сути Ислама) (и может быть уверуют, когда узнают)», сура «Ат-Тауба»/6 аят."],["p","96/14 – Второй аят:"],["p","Всевышний Аллах сказал: «А если они [неверующие] склонятся к миру, то и ты склонись к нему [к миру] и полагайся на Аллаха [не беспокойся, что они могут поступить вероломно]: (ведь) поистине, Он  Слышащий (их речи), (и) Знающий (их деяния)!», сура «Аль-Анфаль»/61 аят."],["p","97/15 – Третий аят:"],["p","Всевышний Аллах сказал: (Это положение) не относится к тем многобожникам, с которыми вы (о, верующие) заключили договор (на определённый срок), а потом они ни в чём не нарушали его [договор] пред вами и никому (из ваших врагов) не помогали (сражаться) против вас! Исполняйте же договор с ними до их срока [до установленного по договору времени]: ведь поистине, Аллах любит остерегающихся (наказания Аллаха) [тех, которые исполняют Его повеления и сторонятся того, что Он запретил]!», сура «Ат-Тауба»/4 аят."],["h3","<b>Глава: Договор с иудеями и христианами о проживании на землях мусульман с предоставлением им защиты </b>"],["p","98/16 – Первый аят:"],["p","Всевышний Аллах сказал: «Сражайтесь (о, верующие) с теми, кто не верует в Аллаха и в Последний день, не запрещает того [не отстраняется от того], что запретил Аллах и Его посланник, и не придерживается Веры Истины [законоположений Ислама] – из (числа) тех, которым даровано Писание [из числа иудеев и христиан], пока они не дадут [будут платить] (вам) откупную дань своей рукой, будучи униженными (и покорными) [побеждёнными]», сура «Ат-Тауба»/29 аят."],["sep",""],["sc","img/word-92/image52.webp",295,502,"f"],["c","Книга Торговли"],["h2","<b>Книга Торговли (1)</b>"]],[["p","99/1 – Первый аят:"],["p","Всевышний Аллах сказал: «А Аллах разрешил торговлю», сура «Аль-Бакара»/275 аят."],["p","100/2 – Второй аят:"],["p","Всевышний Аллах сказал: «Если это только не торговля по взаимному согласию между вами», сура «Ан-Ниса»/29 аят."],["p","101/3 – Третий аят:"],["p","Всевышний Аллах сказал: «И испытывайте сирот (которые находятся на вашем попечении) (на умение правильно распоряжаться имуществом), пока они не достигнут брачного возраста. А если вы заметите в них правильность [праведность в Вере и умение правильно распоряжаться имуществом], то отдавайте им их имущество. И не пожирайте его [имущество сирот] расточительно и торопливо, пока они не вырастут (и не заберут у вас своего имущества). А кто (из вас) богат, пусть будет воздержан (и ничего не берёт с имущества сироты); а кто (из вас) беден, пусть ест согласно мере [по мере необходимости] (когда вынужден). А когда вы отдаете им [сиротам] их имущество, то берите к ним свидетелей (чтобы застраховать себя от непризнания ими этой передачи). И довольно того, что Аллах ведёт счёт!», сура «Ан-Ниса»/6 аят."],["p","102/4 – Четвертый аят:"],["p","Всевышний Аллах сказал: «И не поедайте ваши имущества между собой незаконно [пусть одни из вас не посягают на имущество других, не имея на это права]», сура «Аль-Бакара»/188 аят."],["p","(1) Общее число аятов, которые приводит Ибн Касим в книге Продажи – 50 аятов."],["sc","img/word-92/image53.webp",295,509,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","103/5 – Пятый аят:"],["p","Всевышний Аллах сказал: «И (ведь) Он уже разъяснил вам, что вам запрещено», сура «Аль-Анам»/119 аят."],["p","104/6 – Шестой аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Поистине, опьяняющие [всё, что затмевает разум], азартные игры, жертвенники [камни, где многобожники совершают жертвоприношение], и стрелы [принятие решения по стрелам] (является) мерзостью [скверной] из деяния сатаны [грехом, который он разукрасил]. Сторонитесь же этого, чтобы вы оказались счастливыми! (90) Сатана желает лишь заронить среди вас вражду и ненависть при помощи опьяняющего [всего, что затмевает разум] и азартных игр, и отклонить вас от поминания Аллаха и молитвы. Прекратите ли вы (совершение этого) (после разъяснения вам вреда)?», сура «Аль-Маида»/90-91 аяты."],["h2","<b>Раздел: О том, что запрещено в продаже</b>"]],[["p","105/7 – Первый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Когда призывают на (еженедельную общую) молитву в пятничный день, то устремляйтесь к поминанию Аллаха [на проповедь и общую молитву] и оставьте торговлю (и всё другое, что отвлекает вас). Это [то, что вам повелено] лучше для вас (так как этим Аллах прощает грехи и даёт награду), если бы вы только знали!», сура «Аль-Джума»/9 аят."],["h2","<b>Глава: Условия продажи</b>"],["p","106/8 – Первый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали (в Аллаха, Его Посланника и подчинились Его Закону)! Верно исполняйте договора [свои обязательства перед Аллахом и друг перед другом в том, что не противоречит Книге Аллаха и Сунне Его Посланника]», сура «Аль-Маида»/1 аят."],["sc","img/word-92/image54.webp",295,502,"f"],["c","Книга Торговли"],["h2","<b>Глава: О ростовщичестве</b>"],["p","107/9 – Первый аят:"],["p","Всевышний Аллах сказал: «Те, которые пожирают [берут] рост [ростовщическую прибыль], восстанут (в День Воскрешения из своих могил) только такими же, как восстаёт тот, кого повергает сатана своим прикосновением [как одержимый бесом]. Это [такое воскрешение] (будет им) за то, что они сказали: «Ведь торговля тоже подобна ростовщичеству». А Аллах разрешил торговлю и запретил ростовщичество. К кому придёт увещание [положение о запрете ростовщичества] от его Господа (после того, как он совершил ростовщические сделки) и он удержится (от ростовщичества, покаявшись), тому (будет прощено), что предшествовало (до этого) [ему будут прощены прежние ростовщические сделки]: и дело его (в День Суда будет) у Аллаха; а кто вернётся [продолжит заниматься ростовщичеством], то те (станут) обитателями Огня, (и) они в нём будут вечно пребывать». (275) Уничтожает Аллах ростовщичество [погубит имущество ростовщика и делает такое имущество лишенным благодати] и увеличивает милостыни [многократно увеличивает награду за милостыню и делает имущество благодатным]. И Аллах не любит всякого неверного грешника! (276)», сура «Аль-Бакара»/275-276 аяты."]],[["p","108/10 – Второй аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и, сторонясь того, что Он запретил) и оставьте то, что осталось из роста, если вы (истинно) верующие. (278) Если же вы этого не сделаете [если не оставите то, что осталось из роста], то услышьте [знайте] о войне от Аллаха и Его Посланника. А если вы покаетесь (в ростовщичестве), то вам (принадлежит) основа вашего имущества (но не рост). Вы не притесните (потому что, вы не берёте рост), и вы (сами) не будете притеснены (потому что, не будет убавлена основа вашего имущества)! (279)», сура «Аль-Бакара»/278-279 аяты."],["p","109/11 –Третий аят (1):"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Не пожирайте роста [не занимайтесь ростовщичеством], (которое затем становится) увеличенным многократно, и остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и сторонясь того, что Он запретил), – может быть, вы обретёте счастье [прямо войдёте в Рай]!», сура «Аль Имран»/130 аят."],["p","(1) Этот аят отсутствует в издании «Основы издания шариатских постановлений», имеющемся в продаже, но он приводится в его толковании «Шариатские постановления», 3/155"],["sc","img/word-92/image55.webp",337,503,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Продажа товара, которого еще нет в наличии</b>"],["p","110/12 – Первый аят:"],["p","Всевышний Аллах сказал: «И одолжайте Аллаху хороший заем [давайте милостыню из своего имущества]. И что вы уготовите вперёд из добра [какое бы благодеяние ни сделали] для самих себя, найдёте это (в День Суда) у Аллаха лучшим и большим по награде. И просите прощения у Аллаха. Поистине, Аллах – прощающий (тех, которые обращаются к Нему с покаянием), милосердный (к ним)!», сура «Аль-Муззаммиль»/20 аят."],["h2","<b>Глава: Заем</b>"]]];
